// api/index.ts
// Express API for the collection calendar, deployable to Vercel as a single function.
//
//   Public (no login, used by the Sitecore component):
//     GET /api/addresses?council=karratha&q=174 eddystone   -> autocomplete
//     GET /api/collections?addressId=214469                  -> next collection dates
//
//   Auth:
//     POST /api/auth/login  { email, password } -> { token }
//     GET  /api/auth/me
//
//   Admin (Authorization: Bearer <token>), generic CRUD generated by ZenStack from schema.zmodel:
//     GET/POST/PATCH/DELETE /api/model/council, /api/model/address,
//                           /api/model/collectionSchedule, /api/model/importLog

import express, { Request, Response, NextFunction } from 'express';
import cors from 'cors';
import jwt from 'jsonwebtoken';
import bcrypt from 'bcryptjs';
import { PrismaClient, RunType } from '@prisma/client';
import { enhance } from '@zenstackhq/runtime';
import { ZenStackMiddleware } from '@zenstackhq/server/express';
import { RestApiHandler } from '@zenstackhq/server/api';

// Reuse one PrismaClient across warm serverless invocations
const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };
const prisma = globalForPrisma.prisma ?? new PrismaClient();
if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma;

const app = express();
app.use(express.json({ limit: '1mb' }));

// Only let your Sitecore sites call the API from the browser
// ALLOWED_ORIGINS="https://www.karratha.wa.gov.au,https://karratha.localhost"
const allowed = (process.env.ALLOWED_ORIGINS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
app.use(
    cors({
        origin: allowed.length ? allowed : true, // allow all only when nothing is configured (local dev)
        methods: ['GET', 'POST', 'PATCH', 'PUT', 'DELETE'],
    })
);

// ─────────────────────────────────────────────
// Authentication
//
//   POST /api/auth/login  { email, password }  -> { token, user }
//   GET  /api/auth/me     (Authorization: Bearer <token>)
//
// Every request runs through `authenticate`, which sets req.user from the Bearer token.
// No token -> anonymous: ZenStack policies make everything read-only and hide customerId.
// ─────────────────────────────────────────────
type AuthUser = { id: number; email: string; role: 'ADMIN' | 'COUNCIL_EDITOR'; councilId: number | null };

declare global {
    // eslint-disable-next-line @typescript-eslint/no-namespace
    namespace Express {
        interface Request {
            user?: AuthUser;
        }
    }
}

const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET || JWT_SECRET.length < 32) {
    throw new Error('JWT_SECRET must be set to a random string of at least 32 characters');
}
const TOKEN_TTL = process.env.JWT_TTL ?? '8h';

// Compared against when the email doesn't exist, so response time doesn't reveal valid emails
const DUMMY_HASH = bcrypt.hashSync('not-a-real-password', 10);

function signToken(user: AuthUser) {
    return jwt.sign({ sub: String(user.id), role: user.role }, JWT_SECRET!, {
        expiresIn: TOKEN_TTL as jwt.SignOptions['expiresIn'],
    });
}

const authenticate = async (req: Request, res: Response, next: NextFunction) => {
    const header = req.header('authorization') ?? '';
    const token = header.startsWith('Bearer ') ? header.slice(7) : null;
    if (!token) return next();

    try {
        const payload = jwt.verify(token, JWT_SECRET!) as jwt.JwtPayload;
        // Load from the DB each time so role changes and deleted users take effect immediately
        const user = await prisma.user.findUnique({
            where: { id: Number(payload.sub) },
            select: { id: true, email: true, role: true, councilId: true },
        });
        if (!user) return res.status(401).json({ error: 'User no longer exists' });
        req.user = user;
        next();
    } catch {
        res.status(401).json({ error: 'Invalid or expired token' });
    }
};

const requireUser = (req: Request, res: Response, next: NextFunction) =>
    req.user ? next() : res.status(401).json({ error: 'Login required' });

// Basic brute-force protection: 5 failed attempts per email+IP per 15 minutes.
// In-memory, so it resets on cold starts; use Upstash/Redis or Vercel Firewall for stronger limits.
const failedLogins = new Map<string, { count: number; until: number }>();
const LOGIN_WINDOW = 15 * 60 * 1000;
const MAX_ATTEMPTS = 5;

app.use(authenticate);

app.post('/api/auth/login', async (req, res, next) => {
    try {
        const email = String(req.body?.email ?? '').trim().toLowerCase();
        const password = String(req.body?.password ?? '');
        if (!email || !password) return res.status(400).json({ error: 'Email and password are required' });

        const key = `${email}|${req.ip}`;
        const entry = failedLogins.get(key);
        if (entry && entry.count >= MAX_ATTEMPTS && entry.until > Date.now()) {
            return res.status(429).json({ error: 'Too many attempts. Try again in 15 minutes.' });
        }

        // Raw client on purpose: the enhanced client omits the password field
        const found = await prisma.user.findUnique({ where: { email } });
        const ok = await bcrypt.compare(password, found?.password ?? DUMMY_HASH);

        if (!found || !ok) {
            const count = entry && entry.until > Date.now() ? entry.count + 1 : 1;
            failedLogins.set(key, { count, until: Date.now() + LOGIN_WINDOW });
            return res.status(401).json({ error: 'Incorrect email or password' });
        }

        failedLogins.delete(key);
        const user: AuthUser = { id: found.id, email: found.email, role: found.role, councilId: found.councilId };
        res.json({ token: signToken(user), user });
    } catch (e) {
        next(e);
    }
});

app.get('/api/auth/me', requireUser, (req, res) => res.json({ user: req.user }));

// Policy-aware client for this request (anonymous when req.user is undefined)
const db = (req: Request) => enhance(prisma, { user: req.user });

// ─────────────────────────────────────────────
// Schedule helpers (ported from the WP plugin)
// ─────────────────────────────────────────────
const RUN_TYPE_NAMES: Record<RunType, string> = {
    BLK: 'Skip',
    GEN: 'Green',
    GAR: 'General',
    REC: 'Recycling',
    ORG: 'Organics',
};

// Councils span three Australian time zones; "today" must be the council's today
const COUNCIL_TIMEZONES: Record<string, string> = {
    karratha: 'Australia/Perth',
    kalamunda: 'Australia/Perth',
    joondalup: 'Australia/Perth',
    bayswater: 'Australia/Perth',
    noosa: 'Australia/Brisbane',
    gwydir: 'Australia/Sydney',
    'moree-plains': 'Australia/Sydney',
    narrabri: 'Australia/Sydney',
};

// Reference Monday that counts as "week 1" of the fortnightly cycle.
// ASSUMPTION: check this against Classes/search.php in the WP plugin before going live.
const FORTNIGHT_ANCHOR = process.env.FORTNIGHT_ANCHOR_DATE ?? '2016-01-04';

const DAY = 24 * 60 * 60 * 1000;

// Today's date in a time zone, as a UTC-midnight Date (date-only arithmetic, no DST surprises)
function todayIn(timeZone: string): Date {
    const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
    return new Date(`${parts}T00:00:00Z`);
}

// ISO weekday: 1 = Monday ... 7 = Sunday (same as PHP date('N'))
const isoDay = (d: Date) => ((d.getUTCDay() + 6) % 7) + 1;

function nextCollection(dayOfWeek: number, weekly: boolean, weekStart: number, from: Date): Date {
    // next occurrence of the weekday, today included
    let next = new Date(from.getTime() + (((dayOfWeek - isoDay(from)) + 7) % 7) * DAY);
    if (weekly) return next;

    // fortnightly: shift a week if this falls in the wrong week of the cycle
    const anchor = new Date(`${FORTNIGHT_ANCHOR}T00:00:00Z`);
    const weekIndex = Math.floor((next.getTime() - anchor.getTime()) / (7 * DAY));
    const cycleWeek = (((weekIndex % 2) + 2) % 2) + 1; // 1 or 2
    if (cycleWeek !== weekStart) next = new Date(next.getTime() + 7 * DAY);
    return next;
}

const fmt = (d: Date) => d.toISOString().slice(0, 10);

type AddressRow = { id: number; unit: string | null; streetNumber: number | null; street: string | null; suburb: string | null; postcode: string | null };
const addressLabel = (a: AddressRow) =>
    [[a.unit, a.streetNumber].filter(Boolean).join('/'), a.street, a.suburb, a.postcode].filter(Boolean).join(' ');

// Wrap async handlers so errors reach the error middleware
const wrap = (fn: (req: Request, res: Response) => Promise<unknown>) => (req: Request, res: Response, next: NextFunction) =>
    fn(req, res).catch(next);

// ─────────────────────────────────────────────
// Public endpoints for the Sitecore component
// ─────────────────────────────────────────────

// GET /api/addresses?council=karratha&q=174 eddystone
app.get(
    '/api/addresses',
    wrap(async (req, res) => {
        const council = String(req.query.council ?? '').trim();
        const q = String(req.query.q ?? '').trim();
        if (!council || q.length < 3) return res.json({ addresses: [] });

        // every word must match some part of the address
        const terms = q.split(/[\s,\/]+/).filter(Boolean).slice(0, 5);
        const where = {
            council: { slug: council },
            AND: terms.map((t) => {
                const or: object[] = [
                    { street: { contains: t, mode: 'insensitive' as const } },
                    { suburb: { contains: t, mode: 'insensitive' as const } },
                    { postcode: { startsWith: t } },
                    { unit: { equals: t, mode: 'insensitive' as const } },
                ];
                if (/^\d+$/.test(t)) or.push({ streetNumber: Number(t) });
                return { OR: or };
            }),
        };

        const rows = await db(req).address.findMany({
            where,
            select: { id: true, unit: true, streetNumber: true, street: true, suburb: true, postcode: true },
            orderBy: [{ street: 'asc' }, { streetNumber: 'asc' }],
            take: 10,
        });

        res.setHeader('Cache-Control', 'public, s-maxage=300, stale-while-revalidate=86400');
        res.json({ addresses: rows.map((a) => ({ id: a.id, label: addressLabel(a) })) });
    })
);

// GET /api/collections?addressId=214469
app.get(
    '/api/collections',
    wrap(async (req, res) => {
        const addressId = Number(req.query.addressId);
        if (!Number.isInteger(addressId) || addressId <= 0) return res.status(400).json({ error: 'addressId is required' });

        const address = await db(req).address.findUnique({
            where: { id: addressId },
            include: { council: true, schedules: true },
        });
        if (!address) return res.status(404).json({ error: 'Address not found' });

        const today = todayIn(COUNCIL_TIMEZONES[address.council.slug] ?? 'Australia/Sydney');

        const collections = address.schedules
            .map((s) => {
                const next = nextCollection(s.dayOfWeek, s.weekly, s.weekStart, today);
                return {
                    runType: s.runType,
                    typeName: RUN_TYPE_NAMES[s.runType] ?? 'General',
                    frequency: s.weekly ? 'weekly' : 'fortnightly',
                    daysUntil: Math.round((next.getTime() - today.getTime()) / DAY),
                    nextDate: fmt(next),
                    followingDate: fmt(new Date(next.getTime() + (s.weekly ? 7 : 14) * DAY)),
                };
            })
            .sort((a, b) => a.nextDate.localeCompare(b.nextDate));

        res.setHeader('Cache-Control', 'public, s-maxage=3600, stale-while-revalidate=86400');
        res.json({
            address: { id: address.id, label: addressLabel(address), council: address.council.name },
            collections,
        });
    })
);

// ─────────────────────────────────────────────
// Admin CRUD generated by ZenStack (policies from schema.zmodel apply)
// ─────────────────────────────────────────────
const apiHandler = RestApiHandler({
    endpoint: `${process.env.API_BASE_URL ?? 'http://localhost:3000'}/api/model`,
});

app.use(
    '/api/model',
    requireUser, // public visitors use /api/addresses and /api/collections instead
    ZenStackMiddleware({
        // IMPORTANT: return the enhanced client, never the raw PrismaClient,
        // or anyone could create/delete addresses through this endpoint
        getPrisma: (req) => db(req as Request),
        handler: apiHandler,
    })
);

app.get('/api/health', (_req, res) => res.json({ ok: true }));

// Local dev only: serve the test page in /public (Vercel serves /public itself)
if (!process.env.VERCEL) app.use(express.static('public'));

// ─────────────────────────────────────────────
// Errors
// ─────────────────────────────────────────────
app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
});

// Local dev: `npx tsx api/index.ts` -> http://localhost:3000
if (!process.env.VERCEL) {
    const port = Number(process.env.PORT ?? 3000);
    app.listen(port, () => console.log(`API running on http://localhost:${port}`));
}

export default app;